1	#!/usr/bin/env node
2	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
3	import fs from 'node:fs';
4	import { applyPatch, PatchError } from './jsonpatch.mjs';
5	
6	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
7	const MAX_BYTES = 1048576;
8	const MAX_DEPTH = 1000;
9	const STDIN = '-';
10	
11	class CliError extends Error {
12	  constructor(message, code) {
13	    super(message);
14	    this.code = code;
15	  }
16	}
17	
18	function readError(name, reason) {
19	  return new CliError(`Error: ${name}: ${reason}`, 1);
20	}
21	
22	function isDirectory(path) {
23	  try {
24	    return fs.statSync(path).isDirectory();
25	  } catch {
26	    return false;
27	  }
28	}
29	
30	// Reads at most MAX_BYTES + 1 bytes from a file, so oversized inputs stop early.
31	function readFile(path) {
32	  let fd;
33	  try {
34	    fd = fs.openSync(path, 'r');
35	  } catch (err) {
36	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(path, 'no such file');
37	    if (err.code === 'EISDIR' || isDirectory(path)) throw readError(path, 'is a directory');
38	    throw readError(path, 'cannot read');
39	  }
40	  try {
41	    if (fs.fstatSync(fd).isDirectory()) throw readError(path, 'is a directory');
42	    const buf = Buffer.alloc(MAX_BYTES + 1);
43	    let total = 0;
44	    while (total < buf.length) {
45	      const n = fs.readSync(fd, buf, total, buf.length - total, null);
46	      if (n === 0) break;
47	      total += n;
48	    }
49	    if (total > MAX_BYTES) throw readError(path, 'too large');
50	    return buf.subarray(0, total);
51	  } catch (err) {
52	    if (err instanceof CliError) throw err;
53	    throw readError(path, err.code === 'EISDIR' ? 'is a directory' : 'cannot read');
54	  } finally {
55	    fs.closeSync(fd);
56	  }
57	}
58	
59	async function readStdin() {
60	  const chunks = [];
61	  let total = 0;
62	  try {
63	    for await (const chunk of process.stdin) {
64	      total += chunk.length;
65	      if (total > MAX_BYTES) {
66	        process.stdin.destroy();
67	        throw readError('stdin', 'too large');
68	      }
69	      chunks.push(chunk);
70	    }
71	  } catch (err) {
72	    if (err instanceof CliError) throw err;
73	    throw readError('stdin', 'cannot read');
74	  }
75	  return Buffer.concat(chunks);
76	}
77	
78	// Depth of a parsed JSON value, stopping as soon as it exceeds MAX_DEPTH.
79	function tooDeep(value) {
80	  const stack = [[value, 0]];
81	  while (stack.length > 0) {
82	    const [v, depth] = stack.pop();
83	    if (v === null || typeof v !== 'object') continue;
84	    if (depth + 1 > MAX_DEPTH) return true;
85	    for (const child of Object.values(v)) stack.push([child, depth + 1]);
86	  }
87	  return false;
88	}
89	
90	async function load(arg) {
91	  const name = arg === STDIN ? 'stdin' : arg;
92	  const bytes = arg === STDIN ? await readStdin() : readFile(arg);
93	  let text;
94	  try {
95	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
96	  } catch {
97	    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
98	  }
99	  let value;
100	  try {
101	    value = JSON.parse(text);
102	  } catch {
103	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
104	  }
105	  if (tooDeep(value)) throw new CliError(`Error: ${name}: too deep`, 3);
106	  return value;
107	}
108	
109	async function main(args) {
110	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
111	  const [patchArg, docArg = STDIN] = args;
112	  if (patchArg === STDIN && docArg === STDIN) throw new CliError(USAGE, 2);
113	  const patch = await load(patchArg);
114	  const doc = await load(docArg);
115	  let result;
116	  try {
117	    result = applyPatch(doc, patch);
118	  } catch (err) {
119	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
120	    throw err;
121	  }
122	  process.stdout.write(JSON.stringify(result, null, 2) + '\n');
123	}
124	
125	try {
126	  await main(process.argv.slice(2));
127	} catch (err) {
128	  if (!(err instanceof CliError)) throw err;
129	  process.stderr.write(err.message + '\n');
130	  process.exitCode = err.code;
131	}
